import{z as l,x as s,o as A,c as d,q as n,j as r,D as a,d as e,s as o,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"模型风险","description":"","frontmatter":{"title":"模型风险","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-model-risk.md","filePath":"quant/dp-model-risk.md","lastUpdated":1791063341000}'),p={name:"quant/dp-model-risk.md"};function D(F,E,m,u,C,h){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="模型风险" tabindex="-1">模型风险 <a class="header-anchor" href="#模型风险" aria-label="Permalink to &quot;模型风险&quot;">​</a></h1><div class="epigraph"><p>深度定价把「模型」从一组方程搬成一条管线：数据、架构、种子、损失与模拟器都是模型的一部分——风险的对象跟着搬家，治理的问询却一字不改：谁挑战了它，失效时谁先知道。</p><footer>—— 据 Board of Governors of the Federal Reserve System, SR 11-7, 2011；Cont, Mathematical Finance, 2006 整理</footer></div><p><a href="/quant/dp-deep-hedging-deep">上一课</a>把整本账的对冲交给网络与冻结的模拟器。至此定价、校准、对冲三条链上都站着神经网络；本课问治理。<a href="/quant/derivative-model-risk">模型风险</a>的经典对象是方程与参数：同一个头寸，换一族测度或一组相关系数，价格动多少；<a href="/quant/sr-11-7-model-risk">SR 11-7</a> 把治理收成两条——有效挑战与独立验证。深度管线把这些对象全部替换：方程换成训练管线，参数换成权重与配方。框架仍适用，因为框架问的从来不是「方程长什么样」，而是「错的时候谁先看见」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>深度管线特有的失效面有四层。其一，训练随机性：种子、初始化与数据顺序让同一条管线重训两次给出不同的价格与对冲——「这个模型的价格」本身是一个分布。其二，外推：网络在训练支撑内插值、支撑外静默外推，报价落出校准域时错误不发散、只「看起来合理」，比数值法发散的错更难察觉。其三，复合误差：系数网络、解算器、对冲网络层层叠加，<a href="/quant/pinn-option-pricing">PINN 课</a>的冻结纪律是特例，一般情形是每层的误差谱互不相知。其四，基准模糊：「正确的价」依赖上一课选定的模拟器与 \\(\\rho\\)——挑战者模型的地位更难立，因为连参照系都是模型。</p><p><span class="marginnote">Cont 2006 把模型不确定写成一族测度上的上期望。深度时代「一族测度」变成「种子 × 架构 × 数据窗口」的网格：枚举更难，但「把不确定带报出来」这一要求一字未变。</span></p><p><span class="marginnote">「报价是一个分布」代入数字：同一条管线换 20 个随机种子重训，某期权报价在 10.32 到 10.51 之间散开，极差近 20 个基点。这个极差不是 bug，而是管线对种子的敏感度，应当作为不确定带随报价一起交付，而不是只报一个点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证协议按失效面逐条立。随机性：固定预算内多种子重训，输出分布当不确定带；带太宽本身是发现——说明管线对无关细节敏感。外推：输入落在训练支撑之外的检测器与回退路径（回数值法或参数模型），域外不报价是默认策略。复合：每层冻结后单独验证，误差谱分层记账。挑战者制度保持经典形态：参数模型（Heston、局部波动）、上一版网络、极简基线同台报价，分歧超阈值的头寸进人工清单。治理件：<a href="/quant/model-risk-inventory">模型台账</a>记训练配方——数据窗口、清洗规则、种子、超参、早停点——配方即模型，版本与回滚绑定；上线后监控特征分布与残差的双重漂移；失效判据（价格误差、对冲误差分位、希腊一致性）在上线前钉死，不由事后解释权决定。</p>',9)),(A(),r(i,null,{default:a(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIPE%5B%22%E8%AE%AD%E7%BB%83%E7%AE%A1%E7%BA%BF%EF%BC%9A%E6%95%B0%E6%8D%AE%2F%E7%A7%8D%E5%AD%90%2F%E6%9E%B6%E6%9E%84%22%5D%20--%3E%20NET%5B%22%E5%AE%9A%E4%BB%B7%E4%B8%8E%E5%AF%B9%E5%86%B2%E7%BD%91%E7%BB%9C%22%5D%0A%20%20NET%20--%3E%20PRD%5B%22%E7%94%9F%E4%BA%A7%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20SEED%5B%22%E5%A4%9A%E7%A7%8D%E5%AD%90%E9%87%8D%E8%AE%AD%22%5D%20--%3E%20BAND%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%E5%B8%A6%22%5D%0A%20%20BAND%20--%3E%20GOV%5B%22%E7%8B%AC%E7%AB%8B%E9%AA%8C%E8%AF%81%E4%B8%8E%E6%9C%89%E6%95%88%E6%8C%91%E6%88%98%22%5D%0A%20%20CHK%5B%22%E6%8C%91%E6%88%98%E8%80%85%EF%BC%9A%E5%8F%82%E6%95%B0%E6%A8%A1%E5%9E%8B%2F%E4%B8%8A%E4%B8%80%E7%89%88%2FBS%22%5D%20--%3E%20GOV%0A%20%20OOD%5B%22%E6%94%AF%E6%92%91%E6%A3%80%E6%B5%8B%EF%BC%9A%E5%9F%9F%E5%A4%96%E5%9B%9E%E9%80%80%22%5D%20--%3E%20PRD%0A%20%20DRIFT%5B%22%E7%89%B9%E5%BE%81%E4%B8%8E%E6%AE%8B%E5%B7%AE%E6%BC%82%E7%A7%BB%E7%9B%91%E6%8E%A7%22%5D%20--%3E%20GOV%0A%20%20GOV%20--%3E%20LEDG%5B%22%E5%8F%B0%E8%B4%A6%EF%BC%9A%E9%85%8D%E6%96%B9%E5%8D%B3%E6%A8%A1%E5%9E%8B%EF%BC%8C%E7%89%88%E6%9C%AC%E7%BB%91%E5%AE%9A%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"深度把模型风险变得更集中而非更分散：失效模式从「发散可察觉」变成「平滑而自信的错误」——网络穿过无套利边界时不会报错，只会给出一条光滑的错价曲线；低密度区域的插值带着训练域内的自信。这解释了为什么治理框架一字不改反而更必要：有效挑战的本质是「另一个独立视角必须能否决它」，而独立视角——数值法、参数模型——恰好是深度管线最容易缺的东西，因为整条管线都是学的，没有一层是推的。失效判据前置的机制理由相同：后验地给一条光滑错价找理由太容易，判据必须在上线前变成数字。",-1)),E[5]||(E[5]=B("p",null,"两种失效形态的差异与各自被谁拦截：",-1)),(A(),r(i,null,{default:a(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20NUM%5B%22%E6%95%B0%E5%80%BC%E6%B3%95%E5%A4%B1%E6%95%88%EF%BC%9A%E5%8F%91%E6%95%A3%E5%8F%AF%E5%AF%9F%E8%A7%89%22%5D%0A%20%20%20%20A1%5B%22%E8%BE%93%E5%85%A5%E8%B6%8A%E5%87%BA%E6%A0%A1%E5%87%86%E5%9F%9F%22%5D%20--%3E%20A2%5B%22%E8%AF%AF%E5%B7%AE%E9%9A%8F%E5%8F%82%E6%95%B0%E5%8F%91%E6%95%A3%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E5%BC%82%E5%B8%B8%E6%8A%A5%E8%AD%A6%E8%A7%A6%E5%8F%91%E4%BA%BA%E5%B7%A5%E4%BB%8B%E5%85%A5%22%5D%0A%20%20end%0A%20%20subgraph%20NET%5B%22%E7%BD%91%E7%BB%9C%E5%A4%B1%E6%95%88%EF%BC%9A%E5%B9%B3%E6%BB%91%E8%80%8C%E8%87%AA%E4%BF%A1%22%5D%0A%20%20%20%20B1%5B%22%E8%BE%93%E5%85%A5%E8%90%BD%E5%85%A5%E4%BD%8E%E5%AF%86%E5%BA%A6%E5%8C%BA%E5%9F%9F%22%5D%20--%3E%20B2%5B%22%E9%9D%99%E9%BB%98%E5%A4%96%E6%8E%A8%EF%BC%9A%E9%94%99%E4%BB%B7%E4%BB%8D%E7%84%B6%E5%85%89%E6%BB%91%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E4%B8%8D%E6%8A%A5%E9%94%99%EF%BC%9A%E4%BB%85%E5%89%8D%E7%BD%AE%E5%88%A4%E6%8D%AE%E5%8F%AF%E6%8B%A6%E6%88%AA%22%5D%0A%20%20end%0A%20%20NUM%20--%3E%20Q%5B%22%E5%90%8C%E4%B8%80%E6%B2%BB%E7%90%86%E9%97%AE%E8%AF%A2%EF%BC%9A%E9%94%99%E7%9A%84%E6%97%B6%E5%80%99%E8%B0%81%E5%85%88%E7%9C%8B%E8%A7%81%22%5D%0A%20%20NET%20--%3E%20Q%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">「平滑而自信的错误」可以想象成一名背题型的学生：题目稍加伪装，他仍笔不停挥地写出工整的错误答案；数值法则像不会做就留白，错误可见。正因如此，拦住深度管线的只能靠考前定好的评分标准——上线前钉死的失效判据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两个上限不可消除：备选模型无法枚举——Cont 的测度族选择本身是模型决策，种子网格只是近似；回测样本对低频事件永远太短——深度管线在「没见过的危机」上的表现没有历史证据，只能靠压力测试与情景外推替代实证。「数据驱动」不豁免：数据窗口、清洗规则、标签定义都是模型决策，全部进台账；管线里没有无主的部分。</p><p><span class="marginnote">初学者容易以为「数据驱动」就能免责：行情数据是真的，所以模型没有假设。实际上窗口取多长、异常值怎么清洗、标签如何定义，全是人为决策——这些决策错了，再真实的数据也救不回来，所以必须逐项写进台账接受检查。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深度管线的四层失效面：训练随机性、静默外推、复合误差、基准模糊。</li><li>验证逐条立：多种子不确定带、域外检测与回退、分层误差谱、挑战者同台。</li><li>配方即模型：数据窗口、种子与早停点全部进台账，版本与回滚绑定。</li><li>失效判据上线前钉成数字；光滑的错价不报错，只能靠前置判据拦截。</li><li>出处：Federal Reserve SR 11-7, 2011；Cont, <em>Mathematical Finance</em>, 2006；Ruf and Wang, <em>Journal of Computational Finance</em>, 2020（综述）。</li></ul>',6))])}const _=l(p,[["render",D]]);export{c as __pageData,_ as default};
